function(container, apiUrl, tables) {
  let sortColumn = null;
  let sortOrder = 'asc';
  let allProjects = [];
  const stoppedStates = ['値引き承認待ち', '高額見積確認待ち', '与信確認待ち', '新規取引先前金待ち', '納期遅延通知待ち', '受領書催促中'];

  async function loadProjects() {
    try {
      const projects = await window.aivicApi.list(0);
      allProjects = projects || [];
      updateSummary();
      applyFilters();
    } catch (e) {
      console.error('Failed to load projects:', e);
    }
  }

  function updateSummary() {
    const counts = { '受注': 0, '進行中': 0, '完了': 0, '停止': 0 };
    allProjects.forEach(p => {
      const status = p.status || '受注';
      if (stoppedStates.includes(status)) counts['停止']++;
      else if (['出荷完了', '受領書回収済み', '返品受付済み', '返品不受付'].includes(status)) counts['完了']++;
      else if (['受注確定', '仕入先手配済み', '納期回答待ち', '入荷待ち', '入荷確認済み', '出荷準備中'].includes(status)) counts['進行中']++;
      else counts['受注']++;
    });
    container.querySelector('#count-received').textContent = counts['受注'];
    container.querySelector('#count-active').textContent = counts['進行中'];
    container.querySelector('#count-completed').textContent = counts['完了'];
    container.querySelector('#count-stopped').textContent = counts['停止'];

    const hasCritical = allProjects.some(p => {
      const deadline = new Date(p.deadline || 0);
      const handlerDeadline = new Date(p.handlerDeadline || 0);
      const now = new Date();
      const threeDays = 3 * 24 * 60 * 60 * 1000;
      return (deadline - now < threeDays && deadline > now) || (handlerDeadline - now < threeDays && handlerDeadline > now);
    });
    if (hasCritical) container.querySelector('#deadline-banner').classList.remove('hidden');
  }

  function applyFilters() {
    const priorityFilter = container.querySelector('#priority-filter').value;
    const statusFilter = container.querySelector('#status-filter').value;
    const searchText = container.querySelector('#search-input').value.toLowerCase();

    let filtered = allProjects.filter(p => {
      const matchPriority = !priorityFilter || (p.priority || '中') === priorityFilter;
      const matchStatus = !statusFilter || (stoppedStates.includes(p.status || '') ? '停止' : (p.status || '受注')) === statusFilter;
      const matchSearch = !searchText || (p.projectNo || '').toLowerCase().includes(searchText) || (p.customerName || '').toLowerCase().includes(searchText);
      return matchPriority && matchStatus && matchSearch;
    });

    if (sortColumn) {
      filtered.sort((a, b) => {
        let aVal = a[sortColumn];
        let bVal = b[sortColumn];
        if (sortColumn === 'deadline' || sortColumn === 'handlerDeadline') {
          aVal = new Date(aVal || 0).getTime();
          bVal = new Date(bVal || 0).getTime();
        }
        const cmp = aVal > bVal ? 1 : aVal < bVal ? -1 : 0;
        return sortOrder === 'asc' ? cmp : -cmp;
      });
    }

    renderTable(filtered);
  }

  function renderTable(projects) {
    const tbody = container.querySelector('#projects-tbody');
    tbody.innerHTML = projects.map(p => {
      const isStoppedState = stoppedStates.includes(p.status || '');
      const deadline = new Date(p.deadline || 0);
      const handlerDeadline = new Date(p.handlerDeadline || 0);
      const now = new Date();
      const threeDays = 3 * 24 * 60 * 60 * 1000;
      const isCritical = (deadline - now < threeDays && deadline > now) || (handlerDeadline - now < threeDays && handlerDeadline > now);
      const isLate = deadline < now || handlerDeadline < now;

      return `<tr class="${isStoppedState ? 'stopped-row' : ''}" onclick="showDetail('${p.id || p.projectNo}')">` +
        `<td>${p.projectNo || '-'}</td>` +
        `<td>${p.customerName || '-'}</td>` +
        `<td><span class="state-badge" data-state="${p.status || '受注'}">` +
        (stoppedStates.includes(p.status || '') ? '停止' : p.status || '受注') + `</span></td>` +
        `<td><span class="badge priority-${(p.priority || '中').toLowerCase()}">` +
        (p.priority || '中') + `</span></td>` +
        `<td>${deadline.toLocaleDateString('ja-JP')}</td>` +
        `<td>${handlerDeadline.toLocaleDateString('ja-JP')}</td>` +
        `<td>${isLate ? '<span class=\"warning-icon\">!</span>' : isCritical ? '<span style=\"color:var(--accent-warning)\">!</span>' : ''}</td>` +
        `</tr>`;
    }).join('');
  }

  window.sortTable = function(col) {
    if (sortColumn === col) sortOrder = sortOrder === 'asc' ? 'desc' : 'asc';
    else { sortColumn = col; sortOrder = 'asc'; }
    applyFilters();
  };

  window.showDetail = function(projectId) {
    const project = allProjects.find(p => p.id === projectId || p.projectNo === projectId);
    if (!project) return;
    const detail = container.querySelector('#detail-content');
    detail.innerHTML = `<div class=\"detail-field\"><label>案件番号</label><value>${project.projectNo || '-'}</value></div>` +
      `<div class=\"detail-field\"><label>顧客名</label><value>${project.customerName || '-'}</value></div>` +
      `<div class=\"detail-field\"><label>ステータス</label><value><span class=\"state-badge\" data-state=\"${project.status || '受注'}\">${stoppedStates.includes(project.status || '') ? '停止' : project.status || '受注'}</span></value></div>` +
      `<div class=\"detail-field\"><label>優先度</label><value>${project.priority || '-'}</value></div>` +
      `<div class=\"detail-field\"><label>納期</label><value>${new Date(project.deadline || 0).toLocaleDateString('ja-JP')}</value></div>` +
      `<div class=\"detail-field\"><label>手配期限</label><value>${new Date(project.handlerDeadline || 0).toLocaleDateString('ja-JP')}</value></div>` +
      `<div class=\"detail-field\"><label>受注金額</label><value>¥${(project.amount || 0).toLocaleString('ja-JP')}</value></div>`;
    container.querySelector('#detail-panel').classList.add('visible');
  };

  window.closeDetailPanel = function() {
    container.querySelector('#detail-panel').classList.remove('visible');
  };

  container.querySelector('#priority-filter').addEventListener('change', applyFilters);
  container.querySelector('#status-filter').addEventListener('change', applyFilters);
  container.querySelector('#search-input').addEventListener('input', applyFilters);
  container.addEventListener('keydown', e => {
    if (e.key === 'Escape') window.closeDetailPanel();
  });

  loadProjects();
}

