      const matchDateFrom = !arrivalFrom || new Date(a.arrivalDate || 0) >= new Date(arrivalFrom);
      const matchDateTo = !arrivalTo || new Date(a.arrivalDate || 0) <= new Date(arrivalTo);
      return matchProject && matchProduct && matchDateFrom && matchDateTo;
    });

