        `<div class=\"grid-item-no\">${a.projectNo || '-'}</div>` +
        `<span class=\"priority-badge ${priorityClass}\">${priority}</span>` +
        `</div>` +
        `<div class=\"grid-item-body\">` +
        `<div>${a.productName || '商品'}</div>` +
        `<div>数量: ${a.quantity || 0}</div>` +
        `<div>予定: ${new Date(a.arrivalDate || 0).toLocaleDateString('ja-JP')}</div>` +
        `</div>` +
        `</div>`;
