    container.querySelector('#detail-status').setAttribute('data-state', arrival.status || '入荷待ち');
    container.querySelector('#detail-priority').textContent = arrival.priority || '中';
    container.querySelector('#detail-priority').className = `priority-badge priority-${(arrival.priority || '中').toLowerCase()}`;
    container.querySelector('#detail-arrival-date').value = new Date(arrival.arrivalDate || 0).toLocaleDateString('ja-JP');
    container.querySelector('#detail-quantity').value = arrival.quantity || 0;
    container.querySelector('#arrival-quantity').value = arrival.quantity || 0;
    container.querySelector('#arrival-confirmer').value = 'ユーザー';

    if (!container.querySelector('#arrival-confirm-date').value) {
      const now = new Date();
      container.querySelector('#arrival-confirm-date').value = now.toISOString().slice(0, 16);
    }

    const isConfirmed = confirmedItems.has(selectedArrival.id || selectedArrival.projectNo);
    const isShipped = shippedItems.has(selectedArrival.id || selectedArrival.projectNo);
    container.querySelector('#ship-btn').disabled = !isConfirmed;
    container.querySelector('#complete-btn').disabled = !isShipped;

    container.querySelector('#detail-panel').classList.add('visible');
  };

  window.closeDetailPanel = function() {
    container.querySelector('#detail-panel').classList.remove('visible');
    selectedArrival = null;
  };

  window.confirmArrival = async function() {
    if (!selectedArrival) return;
    const quantity = container.querySelector('#arrival-quantity').value;
    if (!quantity) {
      alert('入荷数量を入力してください');
      return;
    }
    try {
      await window.aivicApi.update(0, selectedArrival.id || selectedArrival.projectNo, {
        status: '入荷確認済み',
        arrivalQuantity: parseInt(quantity)
      });
      confirmedItems.add(selectedArrival.id || selectedArrival.projectNo);
      container.querySelector('#ship-btn').disabled = false;
      alert('入荷が確認されました');
      loadArrivals();
    } catch (e) {
      console.error('Failed to confirm arrival:', e);
    }
  };

  window.confirmShip = async function() {
    if (!selectedArrival) return;
    try {
      await window.aivicApi.update(0, selectedArrival.id || selectedArrival.projectNo, { status: '出荷準備中' });
      shippedItems.add(selectedArrival.id || selectedArrival.projectNo);
      container.querySelector('#complete-btn').disabled = false;
      alert('出荷記録が確認されました');
      loadArrivals();
    } catch (e) {
      console.error('Failed to record ship:', e);
    }
  };

  window.completeShip = async function() {
    if (!selectedArrival) return;
    try {
      await window.aivicApi.update(0, selectedArrival.id || selectedArrival.projectNo, { status: '出荷完了' });
      alert('出荷が完了しました');
      window.closeDetailPanel();
      loadArrivals();
    } catch (e) {
      console.error('Failed to complete ship:', e);
    }
  };

  container.querySelector('#project-search').addEventListener('input', applyFilters);
  container.querySelector('#product-search').addEventListener('input', applyFilters);
  container.querySelector('#arrival-from').addEventListener('change', applyFilters);
  container.querySelector('#arrival-to').addEventListener('change', applyFilters);
  container.addEventListener('keydown', e => { if (e.key === 'Escape') window.closeDetailPanel(); });

  loadArrivals();
}

function(container, apiUrl, tables) {
  let allProjects = [];
  const stoppedStates = ['値引き承認待ち', '高額見積確認待ち', '与信確認待ち', '新規取引先前金待ち', '納期遅延通知待ち', '受領書催促中'];

  async function loadProjects() {
    try {
      const projects = await window.aivicApi.list(0);
      allProjects = projects || [];
      applyFilters();
    } catch (e) {
      console.error('Failed to load projects:', e);
    }
  }

  window.applyFilters = function() {
    const searchText = container.querySelector('#search-input').value.toLowerCase();
    const statusFilters = Array.from(container.querySelectorAll('.filter-group:nth-child(1) input:checked')).map(e => e.value);
    const priorityFilters = Array.from(container.querySelectorAll('.filter-group:nth-child(2) input:checked')).map(e => e.value);
    const deadlineFilters = Array.from(container.querySelectorAll('.filter-group:nth-child(3) input:checked')).map(e => e.value);

    let filtered = allProjects.filter(p => {
      const searchMatch = !searchText || (p.projectNo || '').toLowerCase().includes(searchText) || (p.customerName || '').toLowerCase().includes(searchText);
      const status = stoppedStates.includes(p.status || '') ? '停止' : (p.status || '受注');
      const statusMatch = statusFilters.length === 0 || statusFilters.includes(status);
      const priorityMatch = priorityFilters.length === 0 || priorityFilters.includes(p.priority || '中');

      let deadlineMatch = true;
      if (deadlineFilters.length > 0) {
        const deadline = new Date(p.deadline || 0);
        const now = new Date();
        const threeDays = 3 * 24 * 60 * 60 * 1000;
        let deadlineStatus = 'ok';
        if (deadline < now) deadlineStatus = 'over';
        else if (deadline - now < threeDays) deadlineStatus = 'warn';
        const statusMap = { 'ok': '期限内', 'warn': '切迫', 'over': '超過' };
        deadlineMatch = deadlineFilters.includes(statusMap[deadlineStatus]);
      }

      return searchMatch && statusMatch && priorityMatch && deadlineMatch;
    });

    renderCards(filtered);
  };

  function renderCards(projects) {
    const list = container.querySelector('#cards-list');
    list.innerHTML = projects.map(p => {
      const status = stoppedStates.includes(p.status || '') ? '停止' : (p.status || '受注');
      const deadline = new Date(p.deadline || 0);
      const now = new Date();
      const threeDays = 3 * 24 * 60 * 60 * 1000;
      let deadlineStatus = 'status-ok';
      let deadlineStatusText = '期限内';
      if (deadline < now) {
        deadlineStatus = 'status-over';
        deadlineStatusText = '超過';
      } else if (deadline - now < threeDays) {
        deadlineStatus = 'status-warn';
        deadlineStatusText = '切迫';
      }

      return `<div class=\"card ${stoppedStates.includes(p.status || '') ? 'stopped' : ''}\" onclick=\"showDetail('${p.id || p.projectNo}')\">` +
        `<div class=\"card-header\">` +
        `<div class=\"card-project-no\">${p.projectNo || '-'}</div>` +
        `<span class=\"priority-badge priority-${(p.priority || '中').toLowerCase()}\">${p.priority || '中'}</span>` +
        `</div>` +
        `<div class=\"card-customer\">${p.customerName || '顧客'}</div>` +
        `<div class=\"card-badges\">` +
        `<span class=\"state-badge\" data-state=\"${p.status || '受注'}\">${status}</span>` +
        `</div>` +
        `<div class=\"card-footer\">` +
        `<div class=\"deadline-date\">${deadline.toLocaleDateString('ja-JP')}</div>` +
        `<span class=\"deadline-status ${deadlineStatus}\">${deadlineStatusText}</span>` +
        `</div>` +
        `</div>`;
    }).join('');
  }

  window.showDetail = function(projectId) {
    const project = allProjects.find(p => p.id === projectId || p.projectNo === projectId);
    if (!project) return;
    const status = stoppedStates.includes(project.status || '') ? '停止' : (project.status || '受注');
    container.querySelector('#detail-title').textContent = project.projectNo || '-';
    const body = container.querySelector('#detail-body');
    body.innerHTML = `<div class=\"detail-row\">` +
      `<div class=\"detail-label\">顧客名</div>` +
      `<div class=\"detail-value\">${project.customerName || '-'}</div>` +
      `</div>` +
      `<div class=\"detail-row\">` +
      `<div class=\"detail-label\">ステータス</div>` +
      `<div class=\"detail-value\"><span class=\"state-badge\" data-state=\"${project.status || '受注'}\">${status}</span></div>` +
      `</div>` +
      `<div class=\"detail-row\">` +
      `<div class=\"detail-label\">優先度</div>` +
      `<div class=\"detail-value\">${project.priority || '中'}</div>` +
      `</div>` +
      `<div class=\"detail-row\">` +
      `<div class=\"detail-label\">納期</div>` +
      `<div class=\"detail-value\">${new Date(project.deadline || 0).toLocaleDateString('ja-JP')}</div>` +
      `</div>` +
      `<div class=\"detail-row\">` +
      `<div class=\"detail-label\">受注金額</div>` +
      `<div class=\"detail-value\">¥${(project.amount || 0).toLocaleString('ja-JP')}</div>` +
      `</div>`;
    container.querySelector('#detail-modal').classList.add('visible');
  };

  window.closeDetail = function() {
    container.querySelector('#detail-modal').classList.remove('visible');
  };

  container.querySelector('#search-input').addEventListener('input', window.applyFilters);
  container.addEventListener('keydown', e => { if (e.key === 'Escape') window.closeDetail(); });

  loadProjects();
}
